Object.assign(SNIP,{});PRESET_NOTES["l29"]={"Ví dụ: Max trong mọi cửa sổ độ dài 3": "Vùng sáng là cửa sổ hiện tại. Hàng đợi chứa chỉ số: khi i = 4 (a[4] = 5), mọi chỉ số đang chờ đều bị 5 che nên bị bỏ hết. Kết quả: 3 3 5 5 6 7.", "Ví dụ: Min trong mọi cửa sổ độ dài 3": "Chỉ đổi chiều so sánh: bỏ ở cuối những số ≥ a[i]. Hàng đợi tăng dần, đầu là min. Kết quả: 2 2 -5 -5 -5 1.", "Ví dụ: Đoạn dài nhất có max − min ≤ K": "Hai hàng đợi chạy song song: đầu mx là max, đầu mn là min của đoạn [l, r]. Đoạn tốt nhất là 4 7 6 5 (max − min = 3), dài 4.", "Lỗi: quên bỏ phần tử đã ra khỏi cửa sổ": "Số 9 ở chỉ số 0 không bị ai che (không có số nào lớn hơn) nên nằm mãi ở đầu hàng đợi: mọi cửa sổ đều báo max là 9. Đúng phải là 9 2 3 3 4. Hàng đợi cần cả hai cách bỏ: ra khỏi cửa sổ (ở đầu) và bị che (ở cuối)."};EX_HINTS["l29"]=[["Hàng đợi lưu chỉ số. Mỗi bước: bỏ ở đầu chỉ số đã ra khỏi cửa sổ (≤ i − k), bỏ ở cuối những chỉ số có giá trị ≤ a[i], rồi thêm i.", "Từ i = k − 1 trở đi, a[dq.front()] là max của cửa sổ kết thúc tại i.", "Mỗi chỉ số vào, ra hàng đợi nhiều nhất một lần: O(n), không phụ thuộc k."], ["Cửa sổ co giãn như Bài 12: r tiến từng bước; khi max − min > K thì l tiến cho tới khi hợp lệ.", "Hai hàng đợi: mx giảm dần (đầu là max), mn tăng dần (đầu là min). Khi l vượt qua chỉ số ở đầu hàng đợi nào thì bỏ chỉ số đó.", "Cả l và r chỉ đi tới, mỗi chỉ số vào, ra mỗi hàng đợi một lần: O(n)."], ["dp[i] là tổng điểm lớn nhất khi đứng ở hòn i. Hòn trước đó là một j trong [i − k, i − 1], nên dp[i] = v[i] + max dp[j].", "“max dp[j] với j trong k hòn trước” là max trong cửa sổ trượt trên dãy dp: giữ hàng đợi đơn điệu các chỉ số j.", "Thứ tự trong mỗi bước: bỏ chỉ số quá xa ở đầu, tính dp[i] từ đầu hàng đợi, rồi mới đưa i vào cuối."]];
