RACE_X["race-a29"]=Object.assign(RACE_X["race-a29"]||{},{cs:["using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), k = int.Parse(t[1]);\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        StringBuilder sb = new StringBuilder();\n        for (int i = k - 1; i < n; i++)\n        {\n            int m = a[i];\n            for (int j = i - k + 1; j < i; j++) if (a[j] > m) m = a[j];\n            sb.Append(m).Append(' ');\n        }\n        Console.WriteLine(sb.ToString().TrimEnd());\n    }\n}", "using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), k = int.Parse(t[1]);\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        LinkedList<int> dq = new LinkedList<int>();     // chỉ số; a[...] giảm dần từ đầu tới cuối\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++)\n        {\n            if (dq.Count > 0 && dq.First.Value <= i - k) dq.RemoveFirst();\n            while (dq.Count > 0 && a[dq.Last.Value] <= a[i]) dq.RemoveLast();\n            dq.AddLast(i);\n            if (i >= k - 1) sb.Append(a[dq.First.Value]).Append(' ');\n        }\n        Console.WriteLine(sb.ToString().TrimEnd());\n    }\n}"]});
RACE_X["race-a29"]=Object.assign(RACE_X["race-a29"]||{},{py:["n, k = map(int, input().split())\na = list(map(int, input().split()))\nout = []\nfor i in range(k - 1, n):\n    m = a[i]\n    for j in range(i - k + 1, i):\n        if a[j] > m:\n            m = a[j]\n    out.append(m)\nprint(*out)", "from collections import deque\n\nn, k = map(int, input().split())\na = list(map(int, input().split()))\ndq = deque()          # chỉ số; a[...] giảm dần từ đầu tới cuối\nout = []\nfor i in range(n):\n    if dq and dq[0] <= i - k:\n        dq.popleft()\n    while dq and a[dq[-1]] <= a[i]:\n        dq.pop()\n    dq.append(i)\n    if i >= k - 1:\n        out.append(a[dq[0]])\nprint(*out)"]});
makeStepRace(document.getElementById("race-a29"),{variants:[{label:"Tìm lại max mỗi cửa sổ: O(n · k)",code:"#include <iostream>\nusing namespace std;\n\nint a[100000];\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    for (int i = k - 1; i < n; i++) {\n        int m = a[i];\n        for (int j = i - k + 1; j < i; j++) if (a[j] > m) m = a[j];\n        cout << m << \" \";\n    }\n    cout << \"\\n\";\n    return 0;\n}"},{label:"Hàng đợi đơn điệu: O(n)",code:"#include <iostream>\n#include <deque>\nusing namespace std;\n\nint a[100000];\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    deque<int> dq;          // ch\u1ec9 s\u1ed1; gi\u00e1 tr\u1ecb gi\u1ea3m d\u1ea7n t\u1eeb \u0111\u1ea7u t\u1edbi cu\u1ed1i\n    for (int i = 0; i < n; i++) {\n        if (!dq.empty() && dq.front() <= i - k) dq.pop_front();\n        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();\n        dq.push_back(i);\n        if (i >= k - 1) cout << a[dq.front()] << \" \";\n    }\n    cout << \"\\n\";\n    return 0;\n}"}],gen:n=>n+" "+Math.floor(n/2)+"\n"+Array.from({length:n},(_,i)=>(i*37)%101).join(" "),ns:[50,100,200,400],note:"Cửa sổ dài bằng nửa dãy. Cách tìm lại tốn khoảng n · k / 2 bước; hàng đợi đơn điệu chỉ đẩy vào, lấy ra mỗi chỉ số một lần dù k lớn bao nhiêu."});
const PR29=[{label:"Ví dụ: Max trong mọi cửa sổ độ dài 3",input:"",code:"#include <iostream>\n#include <deque>\nusing namespace std;\n\nint a[8] = {1, 3, -1, -3, 5, 3, 6, 7};\n\nint main() {\n    int n = 8, k = 3;\n    deque<int> dq;          // chỉ số; a[...] giảm dần từ đầu tới cuối\n    for (int i = 0; i < n; i++) {\n        if (!dq.empty() && dq.front() <= i - k) dq.pop_front();   // ra khỏi cửa sổ\n        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back(); // bị a[i] che\n        dq.push_back(i);\n        if (i >= k - 1) cout << a[dq.front()] << \" \";\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i"],range:["i-k+1","i"]},{type:"cont",of:"dq",label:"dq (chỉ số)"}],py:{code:"from collections import deque\n\na = [1, 3, -1, -3, 5, 3, 6, 7]\nn, k = len(a), 3\ndq = deque()          # chỉ số; a[...] giảm dần từ đầu tới cuối\nout = []\nfor i in range(n):\n    if dq and dq[0] <= i - k:\n        dq.popleft()                  # ra khỏi cửa sổ\n    while dq and a[dq[-1]] <= a[i]:\n        dq.pop()                      # bị a[i] che\n    dq.append(i)\n    if i >= k - 1:\n        out.append(a[dq[0]])\nprint(*out)",viz:[{type:"bars",of:"a",ptr:["i"],range:["i-k+1","i"]},{type:"cont",of:"dq",label:"dq (chỉ số)",as:"deque"}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 1, 3, -1, -3, 5, 3, 6, 7 };\n        int n = a.Length, k = 3;\n        LinkedList<int> dq = new LinkedList<int>();     // chỉ số; a[...] giảm dần từ đầu tới cuối\n        for (int i = 0; i < n; i++)\n        {\n            if (dq.Count > 0 && dq.First.Value <= i - k) dq.RemoveFirst();       // ra khỏi cửa sổ\n            while (dq.Count > 0 && a[dq.Last.Value] <= a[i]) dq.RemoveLast();    // bị a[i] che\n            dq.AddLast(i);\n            if (i >= k - 1) Console.Write(a[dq.First.Value] + \" \");\n        }\n        Console.WriteLine();\n    }\n}",viz:[{type:"bars",of:"a",ptr:["i"],range:["i-k+1","i"]},{type:"cont",of:"dq",label:"dq (chỉ số)",as:"deque"}]}},{label:"Ví dụ: Min trong mọi cửa sổ độ dài 3",input:"",code:"#include <iostream>\n#include <deque>\nusing namespace std;\n\nint a[8] = {4, 2, 12, 11, -5, 7, 8, 1};\n\nint main() {\n    int n = 8, k = 3;\n    deque<int> dq;          // chỉ số; a[...] tăng dần từ đầu tới cuối\n    for (int i = 0; i < n; i++) {\n        if (!dq.empty() && dq.front() <= i - k) dq.pop_front();\n        while (!dq.empty() && a[dq.back()] >= a[i]) dq.pop_back();\n        dq.push_back(i);\n        if (i >= k - 1) cout << a[dq.front()] << \" \";\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i"],range:["i-k+1","i"]},{type:"cont",of:"dq",label:"dq (chỉ số)"}],py:{code:"from collections import deque\n\na = [4, 2, 12, 11, -5, 7, 8, 1]\nn, k = len(a), 3\ndq = deque()          # chỉ số; a[...] tăng dần từ đầu tới cuối\nout = []\nfor i in range(n):\n    if dq and dq[0] <= i - k:\n        dq.popleft()                  # ra khỏi cửa sổ\n    while dq and a[dq[-1]] >= a[i]:\n        dq.pop()                      # bị a[i] che\n    dq.append(i)\n    if i >= k - 1:\n        out.append(a[dq[0]])\nprint(*out)",viz:[{type:"bars",of:"a",ptr:["i"],range:["i-k+1","i"]},{type:"cont",of:"dq",label:"dq (chỉ số)",as:"deque"}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 4, 2, 12, 11, -5, 7, 8, 1 };\n        int n = a.Length, k = 3;\n        LinkedList<int> dq = new LinkedList<int>();     // chỉ số; a[...] tăng dần từ đầu tới cuối\n        for (int i = 0; i < n; i++)\n        {\n            if (dq.Count > 0 && dq.First.Value <= i - k) dq.RemoveFirst();       // ra khỏi cửa sổ\n            while (dq.Count > 0 && a[dq.Last.Value] >= a[i]) dq.RemoveLast();    // bị a[i] che\n            dq.AddLast(i);\n            if (i >= k - 1) Console.Write(a[dq.First.Value] + \" \");\n        }\n        Console.WriteLine();\n    }\n}",viz:[{type:"bars",of:"a",ptr:["i"],range:["i-k+1","i"]},{type:"cont",of:"dq",label:"dq (chỉ số)",as:"deque"}]}},{label:"Ví dụ: Đoạn dài nhất có max − min ≤ K",input:"",code:"#include <iostream>\n#include <deque>\nusing namespace std;\n\nint a[9] = {8, 2, 4, 7, 6, 5, 9, 3, 4};\n\nint main() {\n    int n = 9, K = 3;\n    deque<int> mx, mn;      // mx: giảm dần (đầu là max), mn: tăng dần (đầu là min)\n    int l = 0, best = 0;\n    for (int r = 0; r < n; r++) {\n        while (!mx.empty() && a[mx.back()] <= a[r]) mx.pop_back();\n        mx.push_back(r);\n        while (!mn.empty() && a[mn.back()] >= a[r]) mn.pop_back();\n        mn.push_back(r);\n        while (a[mx.front()] - a[mn.front()] > K) {   // cửa sổ không hợp lệ: l tiến\n            l++;\n            if (mx.front() < l) mx.pop_front();\n            if (mn.front() < l) mn.pop_front();\n        }\n        if (r - l + 1 > best) best = r - l + 1;\n    }\n    cout << best << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["l","r"],range:["l","r"]},{type:"cont",of:"mx",label:"mx (chỉ số)"},{type:"cont",of:"mn",label:"mn (chỉ số)"}],py:{code:"from collections import deque\n\na = [8, 2, 4, 7, 6, 5, 9, 3, 4]\nK = 3\nmx, mn = deque(), deque()   # mx: đầu là max, mn: đầu là min của đoạn [l, r]\nl = best = 0\nfor r in range(len(a)):\n    while mx and a[mx[-1]] <= a[r]:\n        mx.pop()\n    mx.append(r)\n    while mn and a[mn[-1]] >= a[r]:\n        mn.pop()\n    mn.append(r)\n    while a[mx[0]] - a[mn[0]] > K:     # cửa sổ không hợp lệ: l tiến\n        l += 1\n        if mx[0] < l:\n            mx.popleft()\n        if mn[0] < l:\n            mn.popleft()\n    best = max(best, r - l + 1)\nprint(best)",viz:[{type:"bars",of:"a",ptr:["l","r"],range:["l","r"]},{type:"cont",of:"mx",label:"mx (chỉ số)",as:"deque"},{type:"cont",of:"mn",label:"mn (chỉ số)",as:"deque"}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 8, 2, 4, 7, 6, 5, 9, 3, 4 };\n        int n = a.Length, K = 3;\n        LinkedList<int> mx = new LinkedList<int>(), mn = new LinkedList<int>();   // đầu mx là max, đầu mn là min\n        int l = 0, best = 0;\n        for (int r = 0; r < n; r++)\n        {\n            while (mx.Count > 0 && a[mx.Last.Value] <= a[r]) mx.RemoveLast();\n            mx.AddLast(r);\n            while (mn.Count > 0 && a[mn.Last.Value] >= a[r]) mn.RemoveLast();\n            mn.AddLast(r);\n            while (a[mx.First.Value] - a[mn.First.Value] > K)    // cửa sổ không hợp lệ: l tiến\n            {\n                l++;\n                if (mx.First.Value < l) mx.RemoveFirst();\n                if (mn.First.Value < l) mn.RemoveFirst();\n            }\n            best = Math.Max(best, r - l + 1);\n        }\n        Console.WriteLine(best);\n    }\n}",viz:[{type:"bars",of:"a",ptr:["l","r"],range:["l","r"]},{type:"cont",of:"mx",label:"mx (chỉ số)",as:"deque"},{type:"cont",of:"mn",label:"mn (chỉ số)",as:"deque"}]}},{label:"Lỗi: quên bỏ phần tử đã ra khỏi cửa sổ",input:"",code:"#include <iostream>\n#include <deque>\nusing namespace std;\n\nint a[6] = {9, 1, 2, 3, 1, 4};\n\nint main() {\n    int n = 6, k = 2;\n    deque<int> dq;\n    for (int i = 0; i < n; i++) {\n        // quên: if (!dq.empty() && dq.front() <= i - k) dq.pop_front();\n        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();\n        dq.push_back(i);\n        if (i >= k - 1) cout << a[dq.front()] << \" \";\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i"],range:["i-k+1","i"]},{type:"cont",of:"dq",label:"dq (chỉ số)"}],py:{code:"from collections import deque\n\na = [9, 1, 2, 3, 1, 4]\nn, k = len(a), 2\ndq = deque()\nout = []\nfor i in range(n):\n    # quên: if dq and dq[0] <= i - k: dq.popleft()\n    while dq and a[dq[-1]] <= a[i]:\n        dq.pop()\n    dq.append(i)\n    if i >= k - 1:\n        out.append(a[dq[0]])\nprint(*out)",viz:[{type:"bars",of:"a",ptr:["i"],range:["i-k+1","i"]},{type:"cont",of:"dq",label:"dq (chỉ số)",as:"deque"}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 9, 1, 2, 3, 1, 4 };\n        int n = a.Length, k = 2;\n        LinkedList<int> dq = new LinkedList<int>();\n        for (int i = 0; i < n; i++)\n        {\n            // quên: if (dq.Count > 0 && dq.First.Value <= i - k) dq.RemoveFirst();\n            while (dq.Count > 0 && a[dq.Last.Value] <= a[i]) dq.RemoveLast();\n            dq.AddLast(i);\n            if (i >= k - 1) Console.Write(a[dq.First.Value] + \" \");\n        }\n        Console.WriteLine();\n    }\n}",viz:[{type:"bars",of:"a",ptr:["i"],range:["i-k+1","i"]},{type:"cont",of:"dq",label:"dq (chỉ số)",as:"deque"}]}}];
