makeEx2(document.getElementById("ex-l29"),sim29,[{t:"Max trong cửa sổ trượt",d:"Đầu vào: dòng 1 là n và k (1 ≤ k ≤ n ≤ 10^5); dòng 2 là n số nguyên (|aᵢ| ≤ 10^9). Đầu ra: n − k + 1 số, số thứ i là giá trị lớn nhất của đoạn a[i..i+k−1].",tests:[{in:"8 3\n1 3 -1 -3 5 3 6 7",out:"3 3 5 5 6 7"},{in:"1 1\n5",out:"5"},{in:"4 4\n4 2 12 3",out:"12"},{in:"5 2\n9 8 7 6 5",out:"9 8 7 6"},{in:"5 2\n1 2 3 4 5",out:"2 3 4 5"},{in:"4 3\n7 7 7 7",out:"7 7"},{in:"6 1\n2 -1 2 -1 2 -1",out:"2 -1 2 -1 2 -1"}],start:"#include <iostream>\n#include <deque>\nusing namespace std;\n\nint a[100000];\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    deque<int> dq;          // chỉ số; a[...] giảm dần từ đầu tới cuối\n    cout << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+" "+Math.floor(n/2)+"\n"+Array.from({length:n},(_,i)=>n-i).join(" "),ns:[500,2000,8000],need:"n",limit:n=>60*n+200,why:"Tìm lại max của từng cửa sổ tốn O(n · k); với k = n/2 là O(n²). Hàng đợi đơn điệu chỉ cần O(n)."},py:{start:"from collections import deque\n\nn, k = map(int, input().split())\na = list(map(int, input().split()))\ndq = deque()          # chỉ số; a[...] giảm dần từ đầu tới cuối\nout = []\nprint(*out)",hints:["deque lưu chỉ số. Mỗi bước: bỏ ở đầu chỉ số đã ra khỏi cửa sổ (≤ i − k), bỏ ở cuối những chỉ số có giá trị ≤ a[i], rồi thêm i.","Từ i = k − 1 trở đi, a[dq[0]] là max của cửa sổ kết thúc tại i.","max(a[i - k + 1:i + 1]) cho mỗi i cũng đúng nhưng tốn O(k) mỗi lần: O(n · k)."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), k = int.Parse(t[1]);\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        LinkedList<int> dq = new LinkedList<int>();     // chỉ số; a[...] giảm dần từ đầu tới cuối\n        StringBuilder sb = new StringBuilder();\n        Console.WriteLine(sb.ToString().TrimEnd());\n    }\n}",hints:["LinkedList dùng làm deque, lưu chỉ số. Mỗi bước: bỏ ở đầu chỉ số đã ra khỏi cửa sổ (≤ i − k), bỏ ở cuối những chỉ số có giá trị ≤ a[i], rồi AddLast(i).","Từ i = k − 1 trở đi, a[dq.First.Value] là max của cửa sổ kết thúc tại i.","Mỗi chỉ số vào, ra deque nhiều nhất một lần: O(n), không phụ thuộc k."]}},{t:"Đoạn dài nhất có biên độ nhỏ",d:"Đầu vào: dòng 1 là n và K (1 ≤ n ≤ 10^5, 0 ≤ K ≤ 10^9); dòng 2 là n số nguyên (0 ≤ aᵢ ≤ 10^9). Đầu ra: độ dài lớn nhất của một đoạn liên tiếp có (giá trị lớn nhất − giá trị nhỏ nhất) ≤ K.",tests:[{in:"9 3\n8 2 4 7 6 5 9 3 4",out:"4"},{in:"1 0\n5",out:"1"},{in:"4 0\n1 1 1 1",out:"4"},{in:"6 5\n10 1 2 4 7 2",out:"4"},{in:"8 0\n4 2 2 2 4 4 2 2",out:"3"},{in:"4 3\n1 5 9 13",out:"1"},{in:"8 8\n3 1 4 1 5 9 2 6",out:"8"}],start:"#include <iostream>\n#include <deque>\nusing namespace std;\n\nint a[100000];\n\nint main() {\n    int n, K;\n    cin >> n >> K;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    deque<int> mx, mn;      // mx: đầu là max, mn: đầu là min của đoạn [l, r]\n    int l = 0, best = 0;\n    cout << best << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+" 1000\n"+Array.from({length:n},(_,i)=>(i*37)%101).join(" "),ns:[500,2000,8000],need:"n",limit:n=>90*n+200,why:"Thử mọi đoạn hoặc tính lại max, min sau mỗi lần l tiến tốn O(n²). Hai hàng đợi đơn điệu cho max, min của cửa sổ trong O(1)."},py:{start:"from collections import deque\n\nn, K = map(int, input().split())\na = list(map(int, input().split()))\nmx, mn = deque(), deque()   # mx: đầu là max, mn: đầu là min của đoạn [l, r]\nl = best = 0\nprint(best)",hints:["Cửa sổ co giãn như Bài 12: r tiến từng bước; khi max − min > K thì l tiến cho tới khi hợp lệ.","Hai deque: mx giảm dần (đầu là max), mn tăng dần (đầu là min). Khi l vượt qua chỉ số ở đầu deque nào thì bỏ chỉ số đó.","Cả l và r chỉ đi tới: O(n)."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), K = int.Parse(t[1]);\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        LinkedList<int> mx = new LinkedList<int>(), mn = new LinkedList<int>();   // đầu mx là max, đầu mn là min của [l, r]\n        int l = 0, best = 0;\n        Console.WriteLine(best);\n    }\n}",hints:["Cửa sổ co giãn như Bài 12: r tiến từng bước; khi max − min > K thì l tiến cho tới khi hợp lệ.","Hai deque: mx giảm dần (đầu là max), mn tăng dần (đầu là min). Khi l vượt qua chỉ số ở đầu deque nào thì bỏ chỉ số đó.","Cả l và r chỉ đi tới: O(n)."]}},{t:"Nhảy đá",d:"Có n hòn đá xếp thành hàng, hòn thứ i có điểm vᵢ (có thể âm). Bắt đầu ở hòn 0 (được điểm v₀), mỗi lần nhảy tới một hòn ở phía trước cách không quá k hòn; phải dừng đúng ở hòn n − 1. Tổng điểm là tổng điểm các hòn đã đứng. Đầu vào: n và k (1 ≤ k ≤ n ≤ 10^5), rồi n số vᵢ (|vᵢ| ≤ 10^4). Đầu ra: tổng điểm lớn nhất.",tests:[{in:"6 2\n1 -1 -2 4 -7 3",out:"7"},{in:"1 1\n5",out:"5"},{in:"6 3\n10 -5 -2 4 0 3",out:"17"},{in:"8 2\n1 -5 -20 4 -1 3 -6 -3",out:"0"},{in:"4 3\n-1 -2 -3 -4",out:"-5"},{in:"5 1\n3 3 3 3 3",out:"15"}],start:"#include <iostream>\n#include <deque>\nusing namespace std;\n\nlong long v[100000], dp[100000];\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    for (int i = 0; i < n; i++) cin >> v[i];\n    // dp[i] = v[i] + max(dp[i - k], ..., dp[i - 1]); dp[0] = v[0]\n    cout << dp[n - 1] << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+" "+Math.floor(n/2)+"\n"+Array.from({length:n},(_,i)=>((i*7919)%201)-100).join(" "),ns:[500,2000,8000],need:"n",limit:n=>60*n+200,why:"Tính max dp[j] bằng vòng lặp là O(n · k). Hàng đợi đơn điệu trên dãy dp cho O(n)."},py:{start:"from collections import deque\n\nn, k = map(int, input().split())\nv = list(map(int, input().split()))\ndp = [0] * n\n# dp[i] = v[i] + max(dp[i - k], ..., dp[i - 1]); dp[0] = v[0]\nprint(dp[n - 1])",hints:["dp[i] là tổng điểm lớn nhất khi đứng ở hòn i. Hòn trước đó là một j trong [i − k, i − 1], nên dp[i] = v[i] + max dp[j].","“max dp[j] với j trong k hòn trước” là max trong cửa sổ trượt trên dãy dp: giữ deque đơn điệu các chỉ số j.","Thứ tự trong mỗi bước: bỏ chỉ số quá xa ở đầu, tính dp[i] từ dq[0], rồi mới đưa i vào cuối."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), k = int.Parse(t[1]);\n        long[] v = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        long[] dp = new long[n];\n        // dp[i] = v[i] + max(dp[i - k], ..., dp[i - 1]); dp[0] = v[0]\n        Console.WriteLine(dp[n - 1]);\n    }\n}",hints:["dp[i] là tổng điểm lớn nhất khi đứng ở hòn i. Hòn trước đó là một j trong [i − k, i − 1], nên dp[i] = v[i] + max dp[j].","“max dp[j] với j trong k hòn trước” là max trong cửa sổ trượt trên dãy dp: giữ deque đơn điệu các chỉ số j.","Thứ tự trong mỗi bước: bỏ chỉ số quá xa ở đầu, tính dp[i] từ đầu deque, rồi mới đưa i vào cuối."]}}]);

makeQuiz("quiz29","score29",[{"q": "Hàng đợi đơn điệu cho max: vì sao bỏ chỉ số j khi a[j] ≤ a[i] với j < i?", "o": ["Vì j đã ra khỏi cửa sổ", "Vì j không bao giờ còn là max: mọi cửa sổ sau chứa j đều chứa i", "Để hàng đợi ngắn hơn cho đẹp", "Vì a[j] âm"], "a": 1, "e": "i ở bên phải nên rời cửa sổ sau j, và a[i] không nhỏ hơn a[j]."}, {"q": "Vì sao hàng đợi lưu chỉ số thay vì giá trị?", "o": ["Chỉ số nhỏ hơn", "Để biết phần tử nào đã ra khỏi cửa sổ (so với i − k)", "Vì giá trị có thể âm", "Không có lý do"], "a": 1, "e": "Biết vị trí thì mới biết lúc nào phải bỏ ở đầu."}, {"q": "a = 2 1 4 3, k = 2. Max của các cửa sổ là?", "o": ["2 4 4", "2 1 4", "4 4 3", "1 4 3"], "a": 0, "e": "[2,1] → 2, [1,4] → 4, [4,3] → 4."}, {"q": "Độ phức tạp của max trong cửa sổ trượt bằng hàng đợi đơn điệu?", "o": ["O(n · k)", "O(n log k)", "O(n)", "O(k)"], "a": 2, "e": "Mỗi chỉ số vào, ra hàng đợi nhiều nhất một lần."}]);

